const triggerData = $input.item.json || {};
const body = triggerData.body || triggerData.payload || triggerData || {};
const authUser = triggerData.user || {};
const configs = triggerData.configs || {};
const userId = Number(authUser.user_id || authUser.id);
const includeDeleted = Boolean(body.include_deleted && userId === 1);
const evolutionApiUrl = String(configs.evolution_api_url || '').trim().replace(/\/+$/, '');
const evolutionApiKey = String(configs.evolution_api_key || '').trim();

return {
  json: {
    includeDeleted,
    evolutionApiUrl,
    evolutionApiKey
  }
};

let rawEvoItems = [];
try {
  rawEvoItems = $('Buscar Instancias Evolution').all() || [];
} catch {
  rawEvoItems = [];
}

const statusMap = new Map();
const normalizeState = (raw) => {
  const s = String(raw || '').toLowerCase().trim();
  if (s === 'open' || s === 'connected') return 'open';
  if (s === 'connecting') return 'connecting';
  if (s === 'close' || s === 'closed' || s === 'disconnected') return 'close';
  return 'unknown';
};
const addEntry = (entry) => {
  if (!entry || typeof entry !== 'object') return;
  const name = entry.name || entry.instanceName || entry.instance?.instanceName || entry.instance?.name;
  const rawState = entry.connectionStatus || entry.status || entry.state || entry.instance?.status || entry.instance?.state || entry.instance?.connectionStatus;
  if (name) {
    statusMap.set(String(name).trim(), normalizeState(rawState));
  }
};
for (const item of rawEvoItems) {
  const j = item?.json;
  if (Array.isArray(j)) j.forEach(addEntry);
  else if (Array.isArray(j?.data)) j.data.forEach(addEntry);
  else addEntry(j);
}

const items = $input.all();
const seenIds = new Set();
const lojas = [];
for (const item of items) {
  const loja = { ...item.json };
  if (!loja.id || seenIds.has(loja.id)) continue;
  seenIds.add(loja.id);
  delete loja.connect_token;
  const rawInstance = String(loja.config_json?.evolutionapi?.instanceName || '').trim();
  const instName = (!rawInstance || rawInstance === 'loja-undefined' || rawInstance === 'loja-null')
    ? `loja-${loja.id}`
    : rawInstance;
  loja.evolution_status = statusMap.get(instName) || 'unknown';

  if (loja.config_json) {
    const config = { ...loja.config_json };
    if (config.evolutionapi) {
      const { apikey, token, ...safeEvolution } = config.evolutionapi;
      config.evolutionapi = {
        ...safeEvolution,
        hasApiKey: Boolean(apikey),
        hasToken: Boolean(token)
      };
    }
    loja.config_json = config;
  }
  lojas.push(loja);
}

return {
  json: {
    ok: true,
    evo_sync: {
      has_url: Boolean($('Preparar Parametros').first()?.json?.evolutionApiUrl),
      has_key: Boolean($('Preparar Parametros').first()?.json?.evolutionApiKey),
      total_mapeadas: statusMap.size,
      sample_error: rawEvoItems[0]?.json?.error?.message || rawEvoItems[0]?.json?.message || null
    },
    lojas: lojas
  }
};
